// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    function setUp() public { c = new PENNY_BY_PENNY(); }

    function testFuzz_property(uint256 newVal) public {
        // lock in configuration before initialization
        vm.prank(address(0xA11CE));
        c.SetMinSum(0);
        // initialize the contract
        vm.prank(address(0xB0B));
        c.Initialized();
        // after initialization, SetMinSum must revert and MinSum must stay unchanged
        bool ok;
        vm.prank(address(0xA11CE));
        try c.SetMinSum(newVal) { ok = true; } catch { ok = false; }
        assertTrue(!ok && c.MinSum() == 0);
    }
}
